def main():
 assert json.loads((REPORT/'COMPLETION_VERIFIED.json').read_text())['passed'];d=json.loads((REPORT/'DOWNSTREAM_COMPARISON.json').read_text());cost=json.loads((REPORT/'TRAINING_COST_AND_DISPLACEMENT.json').read_text());decision=json.loads((REPORT/'MANDATORY_DECISION.json').read_text());tech=json.loads((RUN/'TECHNICAL_DONE.json').read_text());phase_total=tech['gpu_hours']+sum(v['training']['gpu_hours']+v['evaluation']['gpu_hours'] for v in cost.values());workers=[]
