 worker_total=sum(v['context_wall_GPUh'] for v in workers);assert phase_total<=17.5 and worker_total<=17.5;write(REPORT/'COSTS.json',{'phase_GPUh':phase_total,'worker_context_wall_GPUh':worker_total,'workers':workers,'technical_GPUh':tech['gpu_hours'],'ceiling_GPUh':17.5,'within_budget':True,'checkpoint_tree_bytes':sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file()),'checkpoint_disk_ceiling_decimal_GB':75,'no_formal_tests_or_extra_variants':True})
 assert json.loads((REPORT/'COSTS.json').read_text())['checkpoint_tree_bytes']<=75*10**9
