 for name in ('Base','S-All','S-Attn','S-MLP'):lines.append('|'+name+'|'+'|'.join(f'{d["models"][name][t]["score"]:.3f}' for t in tasks)+'|')
 lines+=['','同K下，S-Attn相对S-All的EN→SW提高7.958 chrF++（95%区间[6.794,9.118]），英语指令strict提高8.594点（[2.344,14.844]）。但SW→EN非劣门槛和英语阅读优势门槛未通过，不能据此宣布整体学习—保持优势。','', 'S-MLP的SW阅读和SW→EN相对S-All也有改善，且两组单模块模型英语阅读点估计相同；本轮不支持“MLP天然更容易损伤英语”的一般断言。']
 lines+=['','SW阅读64、英语有效阅读63、翻译每方向128来源组、英语指令128。英语原64条全部生成并保留，已知1道源题结构错误在出分前固定不计分。阅读内容与格式分报，数学评分未验收而完全排除；这些是开发代理，不是正式Belebele/IFEval/GSM8K测试。','', '|S-Attn − S-All|差值|来源配对95%区间|','|---|---:|---:|']
 for t in tasks:
  v=d['comparisons']['S-Attn-minus-S-All'][t];lines.append(f'|{labels[t]}|{v["difference"]:+.3f}|[{v["low"]:+.3f}, {v["high"]:+.3f}]|')
 lines+=['','|S-MLP − S-All|差值|来源配对95%区间|','|---|---:|---:|']
 for t in tasks:
  v=d['comparisons']['S-MLP-minus-S-All'][t];lines.append(f'|{labels[t]}|{v["difference"]:+.3f}|[{v["low"]:+.3f}, {v["high"]:+.3f}]|')
 lines+=['','## 生成行为与实际案例','', 'EN→SW任务的语言检测标签：S-All为英语127/128、SW 1/128；S-MLP为英语124/128、SW 4/128；S-Attn为SW 121/128、英语6/128、其他1/128。语言识别是诊断，不是正确翻译率；Attention的chrF++优势可能部分来自更愿意输出目标语言，不能全部解释为语义翻译能力或英语保持。','', '按冻结题目顺序取首两个“All判英语、Attn判SW”的案例（事后示例选择，不是随机抽查）：All/MLP保持英文表达；Attention切换了语言，但首例出现严重重复并达到长度上限，语言切换本身不保证内容正确。助手核验不是独立SW母语金标准。案例ID、选择规则及聚合统计见[BEHAVIOR_AUDIT.json](BEHAVIOR_AUDIT.json)；完整回答仅保存服务器。该诊断不改变评分器、样本或冻结门槛。']
 lines+=['','![全部模块对照](TASK_CONTRASTS.png)','','全部三组两两对照及各自相对Base的来源分组配对区间，见[DOWNSTREAM_COMPARISON.json](DOWNSTREAM_COMPARISON.json)。使用10000次bootstrap、seed42，不按混合任务均分挑方法。','', '## 冻结判定','', '|预定门槛|通过|','|---|---|']
 for k,v in decision['gates'].items():lines.append(f'|{k}|{"是" if v else "否／证据不足"}|')
 lines+=['',f'联合筛查：**{"通过" if decision["passed_task_screen"] else "未通过"}**。{"仅讨论下一步验证，不自动启动额外实验" if decision["passed_task_screen"] else "尚无符合预定条件的Attention优先证据；保留明确的局部优势和不确定性，停止直接扩大当前方案"}。','', '门槛在出分前固定：S-Attn的EN→SW、SW→EN相对S-All配对区间下界各不低于−1 chrF++点，SW阅读不低于−2 F1点；英语阅读内容正确率下界须大于0，指令strict不低于−2点。宽区间代表不确定，不能从不显著推断等效，也不能把非劣未通过都称为已证实伤害。','', '## 相同K下，实际更新是否相同','', '|方法|候选中比例|最终相对Base位移L2|实际更新路径长度和|非零坐标写回事件累计|mask选中并集|','|---|---:|---:|---:|---:|---:|']
 for name,fraction in [('S-All',1/17),('S-Attn',.5),('S-MLP',1/15)]:
  t=cost[name]['training'];union=sum(v['mask_union'] for v in t['final_modules'].values());lines.append(f'|{name}|{100*fraction:.6f}%|{t["final_base_delta_L2"]:.6f}|{t["cumulative_path_length"]:.6f}|{t["cumulative_nonzero_write_events"]}|{union}|')
 ratios=decision['Attn_to_All_displacement_ratios'];lines+=['',f'S-Attn/S-All路径长度比{ratios["cumulative_path_length"]:.4f}，净位移比{ratios["final_base_displacement_L2"]:.4f}。预定低于0.8即标记位移混杂：**{"触发" if decision["displacement_confound_flag"] else "未触发"}**。即使任务指标较好，触发后也需要另行匹配位移强度才可归因于模块位置；本轮没有擅自追加该对照。','', '![真实更新统计](ACTUAL_UPDATES.png)','','mask并集包括LR0或BF16舍入后未实际改变的位置，不能当作实际非零写回并集。非零写回事件累计可重复计同一坐标；最终相对Base变化的坐标及分模块净位移另存[TRAINING_COST_AND_DISPLACEMENT.json](TRAINING_COST_AND_DISPLACEMENT.json)。','', '## 算法与数值验核','', '实际权重形状核算：Attention112矩阵/154,140,672元素，MLP84矩阵/1,156,055,040元素。K=floor(0.5×较小集合)=77,070,336。按矩阵大小分配整数名额，Hamilton余数补齐，稳定模型遍历顺序打破平局。各组分母不同，不能各取15%；历史15%结果未作为本轮匹配S-All使用。详见[BUDGET_FROZEN.json](BUDGET_FROZEN.json)。','', '三组均从相同Qwen2.5-1.5B-Instruct出发，Aya80%+双向翻译各10%的同一前缀；每组4293步、1,536,351输入/599,469监督Token、有效batch2、长度上限2048。沿用稀疏线有效答案逐样本CE，42465步完整学习率日程前缀、warmup2124、峰值5e-5。BF16权重、FP32完整eligible矩阵动量、mask每20步刷新，wd0.01仅在选中候选写回内。','', '为统一裁剪定义，三组都计算196个候选矩阵梯度并全局clip=1，只有各组允许的位置推进FP32动量与写回；embedding/head/Norm/bias冻结。该实现没有把S-Attn的反向成本优化到最低。三组最初两步主损失、完整候选梯度范数、LR和Token计数逐位一致，见[INITIAL_IDENTITY_VERIFIED.json](INITIAL_IDENTITY_VERIFIED.json)。','', '新优化器43步与原无保护AdamW的BF16权重、FP32动量和mask逐位一致。真实Qwen三组最长样本8步预算/冻结位置/写回支持检查通过；S-All完整4→8保存恢复逐位一致。每组2146/4293完整状态和实际加载器经服务器验核，masks/unions仅作无损位压缩；详见[优化器回归](OPTIMIZER_TESTS.json)、[真实预检](TECHNICAL_DONE.json)、[完成验核](COMPLETION_VERIFIED.json)。','', '## 成本与记录','', '|方法|训练GPU小时|评测GPU小时|训练物理显存采样峰值MiB|','|---|---:|---:|---:|']
 for name in ('S-All','S-Attn','S-MLP'):
  t=cost[name]['training'];e=cost[name]['evaluation'];lines.append(f'|{name}|{t["gpu_hours"]:.4f}|{e["gpu_hours"]:.4f}|{t["physical_peak_mib_observed"]}|')
 lines+=['',f'真实预检{tech["gpu_hours"]:.4f} GPU小时；分阶段合计{phase_total:.4f}，工作进程上下文合计{worker_total:.4f} GPU小时，均在17.5上限内。时间包含各阶段持有GPU期间的加载/保存等开销，不等于纯GPU计算时间；等待队列不占卡。见[COSTS.json](COSTS.json)及[硬件](GPU_HARDWARE.csv)。','', '用户临时授权使用全部经核实空闲卡，最多物理8卡，仅适用于本轮；全局队列默认4不变。逐卡检查进程和既有队列预留，没有中断其他任务或空占卡。失败的首次GPU4资源获取只安全退出；之后在GPU5完成真实预检，再按实际空卡分配三组。','', '所有训练配置及哈希、TensorBoard、两份可恢复检查点、逐步非零写回/位移/并集、逐题输出与成对对照均留在服务器。模型目录`models/checkpoint/module_budget_sparse_20261022`，日志`logs/module_budget_sparse_20261022`，逐题对照`work/module_budget_sparse_v1/PAIRED_ITEM_COMPARISONS.jsonl`。公开只含[代码](code)、协议和聚合凭证，不上传题文、回答、权重或旧私有数据历史。','', '若考虑继续，最多先提出一个匹配实际位移强度的S-All对照，以区分更新强度与模块位置；不直接升级子空间或首尾层研究，本轮未执行该新增对照。这是一轮单seed的开发筛查，不能确立Attention或MLP普遍更适合语言适配。与Dense表示对齐轨的动量精度、更新范围、辅助曝光不同，两轨分表，不跨轨排名。没有新增第二seed、位移对照、首尾层或子空间训练；后续只能依据当前证据另行提出具体可证伪方案。']
 (REPORT/'README_ZH.md').write_text('\n'.join(lines)+'\n');print('FINAL MODULE REPORT WRITTEN')
